import { useEffect, useMemo, useRef, useState } from 'react'
import { Activity, AlertTriangle, ArrowRight, Bell, Building2, Camera, Check, ChevronDown, CloudRain, FileText, Layers3, Leaf, LocateFixed, LockKeyhole, LogOut, Map, Menu, Moon, Navigation, Search, ShieldCheck, SlidersHorizontal, Sun, Upload, Users, Waves, X } from 'lucide-react'
import { GovernmentRole, UserRole, useAuth } from './auth'
import { useTheme } from './contexts/ThemeContext'
import { CircleMarker, GeoJSON, MapContainer, Popup, TileLayer, Tooltip, useMap } from 'react-leaflet'
import 'leaflet/dist/leaflet.css'
import { VideoBackdrop } from './components/VideoBackdrop'
import { PublicAssetExplorer, PublicGISExplorer, PublicWatershedExplorer } from './components/PublicPortal'
import { PublicEvidenceExplorer } from './components/PublicSafeEvidence'
import { GovernmentMapControls } from './components/GovernmentMapControls'
import { FieldObservationPage, GovernmentFieldOperations } from './components/GovernmentFieldOperations'
import { GovernmentEvidenceExplorer } from './components/GovernmentEvidence'
import { EvidenceComparisonPage } from './components/EvidenceComparisonPage'
import { LoginExperience } from './components/LoginExperience'
import { SpatialAnalytics as SpatialAnalyticsPage } from './components/SpatialAnalytics'
import { DevelopmentIndicator } from './components/DevelopmentIndicator'
import { PriorityInterventionPage } from './components/PriorityIntervention'
import { GovernmentAlerts } from './components/GovernmentAlerts'
import { PublicReportsPage } from './components/PublicReports'
import { useLocation, useNavigate } from 'react-router-dom'
import { fieldOfficerRestrictedRoutes, restrictedRoutes, viewFromPath, viewPaths, type AppView } from './routes/routes'
import { ControlCenter } from './components/ControlCenter'
import { SearchCommandDialog } from './components/SearchCommandDialog'
import { KPIDetailSheet, type KpiMetric } from './components/KPIDetailSheet'
import { AssetDetailsDialog, WatershedDetailsSheet } from './components/EntityDetails'
import { InteractiveTrendChart } from './components/InteractiveTrendChart'
import { useWorkflow } from './contexts/WorkflowContext'
import { alerts as mockAlerts, assets, fieldObservations, geoImages, governmentReports as mockGovernmentReports, priorityZones, publicReports as mockPublicReports, spatialInsights, watersheds } from './data/mockData'

type View = AppView
type Role = UserRole

const nav: { id: View; label: string; icon: typeof Waves; public?: boolean; roles?: GovernmentRole[] }[] = [
  { id: 'overview', label: 'Dashboard', icon: Waves, public: true, roles: ['administrator', 'district_officer', 'field_officer'] }, { id: 'watersheds', label: 'Watershed Explorer', icon: Map, public: true, roles: ['administrator', 'district_officer', 'field_officer'] },
  { id: 'gis', label: 'GIS Map', icon: Layers3, public: true, roles: ['administrator', 'district_officer', 'field_officer'] }, { id: 'evidence', label: 'Geo-Coded Images', icon: Camera, public: true, roles: ['administrator', 'district_officer', 'field_officer'] },
  { id: 'assets', label: 'Watershed Assets', icon: Building2, public: true, roles: ['administrator', 'district_officer', 'field_officer'] }, { id: 'insights', label: 'Development Insights', icon: Activity, roles: ['administrator', 'district_officer'] },
  { id: 'indicator', label: 'Development Indicator', icon: Activity, public: true, roles: ['administrator', 'district_officer', 'field_officer'] },
  { id: 'operations', label: 'Inspections', icon: ShieldCheck, roles: ['administrator', 'district_officer', 'field_officer'] },
  { id: 'observation', label: 'Field Observation', icon: Navigation, roles: ['administrator', 'district_officer', 'field_officer'] },
  { id: 'before-after', label: 'Before / After', icon: Camera, roles: ['administrator', 'district_officer', 'field_officer'] },
  { id: 'priority', label: 'Priority Intervention', icon: AlertTriangle, roles: ['administrator', 'district_officer'] },
  { id: 'alerts', label: 'Alerts', icon: Bell, roles: ['administrator', 'district_officer', 'field_officer'] },
  { id: 'reports', label: 'Reports', icon: FileText, public: true, roles: ['administrator', 'district_officer'] }
]
function Logo() { return <div className="brand"><div className="mark"><span></span><i></i><b></b></div><div><strong>JAL-IMPACT</strong><small>Geospatial Watershed Intelligence</small></div></div> }
function PlanningContext({ role }: { role: Role }) { const [expanded, setExpanded] = useState(false); return <section className="planning-context" aria-label="Decentralised planning context"><div><span className="planning-chip">SPACE-ENABLED LOCAL PLANNING</span><b>{role === 'government' ? 'Panchayat-ready intelligence for local planning' : 'Panchayat-ready watershed transparency'}</b><small>{expanded ? 'Inspired by public geospatial planning initiatives such as Bhuvan Panchayat: thematic mapping, local assets, water resources and location-aware planning.' : 'Map assets, water resources and development needs in a local planning context.'}</small></div><button onClick={() => setExpanded(value => !value)} aria-expanded={expanded}>{expanded ? 'Show less' : 'Why it matters'} <ArrowRight size={14}/></button></section> }

function App() {
  const { authenticated, role, governmentRole, logout } = useAuth()
  const location = useLocation()
  const routerNavigate = useNavigate()
  const view = viewFromPath(location.pathname)
  const { theme, cycleTheme } = useTheme()
  const workflow = useWorkflow()
  const [menu, setMenu] = useState(false)
  const [focus, setFocus] = useState('Kandhamal Watershed')
  const [govTarget, setGovTarget] = useState<string | null>(null)
  const [govObservationPoint, setGovObservationPoint] = useState<[number, number] | null>(null)
  const [govInspectionTarget, setGovInspectionTarget] = useState<string | null>(null)
  const [govObservationAssetTarget, setGovObservationAssetTarget] = useState<string | null>(null)
  const [publicImageFocus, setPublicImageFocus] = useState<string | null>(null)
  const [govEvidenceAction, setGovEvidenceAction] = useState<{ id: string; action: 'view' | 'analyze' } | null>(null)
  const [compareImage, setCompareImage] = useState<string | null>(null)
  const [kpiMetric, setKpiMetric] = useState<KpiMetric | null>(null)
  const [searchOpen, setSearchOpen] = useState(false)
  const [controlCenterOpen, setControlCenterOpen] = useState(false)
  const [publicWatershedFocus, setPublicWatershedFocus] = useState<string | null>(null)
  useEffect(() => { setMenu(false) }, [location.pathname])
  const visibleNav = useMemo(() => nav.filter(n => role === 'public' ? n.public : n.roles?.includes(governmentRole || 'field_officer')), [role, governmentRole])
  const navigate = (next: View) => { if (next !== 'gis') setGovObservationPoint(null); routerNavigate(viewPaths[next]); setMenu(false) }
  const compareEvidence = (id: string) => { setCompareImage(id); navigate('before-after') }
  const openTarget = (target: string) => { setGovObservationPoint(null); setGovTarget(target) }
  const openWatershed = (id: string) => { workflow.selectWatershed(id); workflow.selectAsset(null); if (role === 'public') { setPublicWatershedFocus(id); setPublicImageFocus(null) } }
  const openAsset = (id: string) => { workflow.selectAsset(id); workflow.selectWatershed(null) }
  const closeRecordDetails = () => { workflow.selectWatershed(null); workflow.selectAsset(null) }
  const prepareImage = (id: string) => { workflow.selectImage(id); if (role === 'government') setGovEvidenceAction({ id, action: 'view' }); else setPublicImageFocus(id) }
  const viewRecordOnMap = (id: string) => { if (role === 'public') { const watershed = id.startsWith('WS-') ? id : assets.find(item => item.id === id)?.watershedId || null; workflow.selectWatershed(watershed); setPublicWatershedFocus(watershed); setPublicImageFocus(id.startsWith('WHS-') ? assets.find(item => item.id === id)?.latestImageId || null : null) } else openTarget(id); navigate('gis') }
  const showOnMap = (coordinates?: [number, number]) => { if (coordinates) { setGovObservationPoint(coordinates); setGovTarget(null) } else { setGovObservationPoint(null); setGovTarget('WHS-021') }; navigate('gis') }
  const restricted = role === 'public' && (restrictedRoutes.some(path => path === location.pathname) || view === 'insights' || view === 'before-after')
  const restrictedSubrole = role === 'government' && (governmentRole || 'field_officer') === 'field_officer' && fieldOfficerRestrictedRoutes.some(path => path === location.pathname)
  if (!authenticated || !role) return <div className="video-page video-theme"><VideoBackdrop/><LoginExperience /></div>
  if (restricted) return <div className="video-page video-theme"><VideoBackdrop/><RestrictedPortal /></div>
  if (restrictedSubrole) return <div className="video-page video-theme"><VideoBackdrop/><SubroleRestrictedPortal /></div>
  return <main className={`app ${theme} video-theme`}>
    <VideoBackdrop />
    <aside className={menu ? 'sidebar open' : 'sidebar'}>
      <Logo />
      <div className={role === 'government' ? 'access-badge government' : 'access-badge'}>{role === 'government' ? <><LockKeyhole size={13}/> SECURE GOVERNMENT ACCESS</> : <><Users size={13}/> PUBLIC PORTAL</>}</div>
      <nav>{visibleNav.map(({ id, label, icon: Icon }) => <button key={id} className={view === id ? 'active' : ''} onClick={() => navigate(id)}><Icon size={18}/><span>{role === 'public' && id === 'overview' ? 'Overview' : role === 'government' && id === 'watersheds' ? 'Watersheds' : role === 'government' && id === 'insights' ? 'Spatial Analytics' : label}</span>{id === 'operations' && <em>3</em>}</button>)}</nav>
      <button type="button" className="district" onClick={() => setControlCenterOpen(true)} aria-label="Open monitoring area and Control Center"><span className="pulse"></span><span><small>Monitoring area</small><b>Odisha · Kandhamal</b></span><ChevronDown size={15}/></button>
      <button className="side-foot logout" onClick={logout}><LogOut size={17}/><span>Sign out</span></button>
    </aside>
    <section className="shell">
      <header><button className="mobile-menu" onClick={() => setMenu(!menu)} aria-label="Toggle navigation">{menu ? <X/> : <Menu/>}</button><div className="crumb"><span>{view === 'gis' ? 'GEOSPATIAL INTELLIGENCE' : view === 'evidence' ? 'GEO-CODED FIELD EVIDENCE' : view === 'operations' ? 'FIELD OPERATIONS' : view === 'insights' ? 'SPATIAL INTELLIGENCE' : view === 'reports' ? 'DECISION SUPPORT' : 'WATER INTELLIGENCE'}</span><p>{role === 'government' ? 'National Watershed Monitoring & Decision Support' : 'Transparency through geospatial intelligence'}</p></div><div className="tools"><button onClick={() => setSearchOpen(true)} aria-label="Search watershed intelligence" title="Search records"><Search size={19}/></button><button aria-label={role === 'government' ? 'Open government alerts' : 'Open public updates'} className="alert-dot" onClick={() => navigate(role === 'government' ? 'alerts' : 'reports')}><Bell size={19}/></button><button onClick={() => setControlCenterOpen(true)} aria-label="Open Control Center" title="Control Center"><SlidersHorizontal size={18}/></button><button onClick={cycleTheme} aria-label={`Switch theme; current theme is ${theme}`}>{theme === 'dark' ? <Sun size={18}/> : theme === 'water' ? <Waves size={18}/> : <Moon size={18}/>}</button><button type="button" className="avatar" onClick={() => setControlCenterOpen(true)} aria-label="Account and Control Center">RK</button></div></header>
      {(view === 'overview' || view === 'gis') && <PlanningContext role={role}/>}
      {view === 'overview' && (role === 'public' ? <><PublicDashboard navigate={navigate} onOpenKpi={setKpiMetric}/><InteractiveTrendChart role={role} onViewObservations={() => navigate('indicator')}/></> : <><GovernmentDashboard navigate={navigate} openTarget={openTarget} onOpenKpi={setKpiMetric}/><InteractiveTrendChart role={role} onViewObservations={() => navigate('observation')}/></>)}
      {view === 'gis' && (role === 'public' ? <PublicGISExplorer navigate={navigate} focusImageId={publicImageFocus} focusWatershedId={publicWatershedFocus} onSelectWatershed={openWatershed} onSelectAsset={openAsset} onSelectImage={prepareImage}/> : <GovernmentGIS target={govTarget} observationPoint={govObservationPoint} clearTarget={() => setGovTarget(null)} navigate={navigate} onSelectWatershed={openWatershed} onSelectAsset={openAsset} onOpenEvidence={id => { setGovEvidenceAction({ id, action: 'view' }); navigate('evidence') }} onAnalyzeEvidence={id => { setGovEvidenceAction({ id, action: 'analyze' }); navigate('evidence') }} onCompareEvidence={compareEvidence}/>)}
      {view === 'evidence' && (role === 'public' ? <PublicEvidenceExplorer navigate={navigate} initialImageId={workflow.selectedImageId} onViewLocation={setPublicImageFocus}/> : <GovernmentEvidenceExplorer initialAction={govEvidenceAction} clearInitialAction={() => setGovEvidenceAction(null)} onCompare={compareEvidence} onViewOnGIS={id => { openTarget(id); navigate('gis') }}/>) }
      {view === 'insights' && role === 'government' && <SpatialAnalyticsPage onOpenWatershed={openWatershed} onOpenAsset={openAsset} navigate={navigate}/>}
      {view === 'indicator' && <DevelopmentIndicator role={role} navigate={navigate}/>}
      {view === 'operations' && role === 'government' && <GovernmentFieldOperations navigate={navigate} onViewOnMap={showOnMap} initialAssetId={govInspectionTarget} onConsumeTarget={() => setGovInspectionTarget(null)} onNewObservation={assetId => { setGovObservationAssetTarget(assetId); navigate('observation') }}/>}
      {view === 'observation' && role === 'government' && <FieldObservationPage navigate={navigate} onViewOnMap={showOnMap} initialAssetId={govObservationAssetTarget} onConsumeTarget={() => setGovObservationAssetTarget(null)}/>}
      {view === 'before-after' && role === 'government' && <EvidenceComparisonPage imageId={compareImage} clearImage={() => setCompareImage(null)}/>}
      {view === 'priority' && role === 'government' && <PriorityInterventionPage onViewMap={assetId => { openTarget(assetId); navigate('gis') }} onViewEvidence={imageId => { setGovEvidenceAction({ id: imageId, action: 'view' }); navigate('evidence') }} onInspect={assetId => { setGovInspectionTarget(assetId); navigate('operations') }}/>}
      {view === 'alerts' && role === 'government' && <GovernmentAlerts onViewMap={target => { openTarget(target); navigate('gis') }} onViewEvidence={imageId => { setGovEvidenceAction(imageId ? { id: imageId, action: 'view' } : null); navigate('evidence') }}/>}
      {view === 'reports' && (role === 'public' ? <PublicReportsPage navigate={navigate}/> : <Reports navigate={navigate}/>)}
      {view === 'watersheds' && (role === 'public' ? <PublicWatershedExplorer navigate={navigate} onSelectWatershed={openWatershed}/> : <ModulePlaceholder view={view} role={role}/>)}
      {view === 'assets' && (role === 'public' ? <PublicAssetExplorer navigate={navigate} onSelectAsset={openAsset}/> : <ModulePlaceholder view={view} role={role}/>)}
      {view === 'inspections' && role === 'government' && <ModulePlaceholder view={view} role={role}/>}
    </section>
    <SearchCommandDialog open={searchOpen} role={role} onClose={() => setSearchOpen(false)} onOpenWatershed={openWatershed} onOpenAsset={openAsset} onOpenImage={id => { prepareImage(id); navigate('evidence') }}/>
    <ControlCenter open={controlCenterOpen} onClose={() => setControlCenterOpen(false)} role={role} governmentRole={governmentRole} theme={theme} onCycleTheme={cycleTheme} onNavigate={navigate} onLogout={logout}/>
    <KPIDetailSheet metric={kpiMetric} role={role} onClose={() => setKpiMetric(null)} onNavigate={navigate} onViewMap={viewRecordOnMap} onOpenWatershed={openWatershed} onOpenAsset={openAsset} onOpenImage={prepareImage}/>
    <WatershedDetailsSheet id={workflow.selectedWatershedId} role={role} onClose={closeRecordDetails} onNavigate={navigate} onViewMap={viewRecordOnMap} onOpenAsset={openAsset} onOpenImage={id => { prepareImage(id); navigate('evidence') }}/>
    <AssetDetailsDialog id={workflow.selectedAssetId} role={role} onClose={closeRecordDetails} onNavigate={navigate} onViewMap={viewRecordOnMap} onOpenImage={id => { prepareImage(id); navigate('evidence') }}/>
    {workflow.toast && <div className={`workflow-toast ${workflow.toast.tone}`} role="status"><Check size={15}/><span><b>{workflow.toast.title}</b>{workflow.toast.detail && <small>{workflow.toast.detail}</small>}</span><button type="button" onClick={workflow.dismissToast} aria-label="Dismiss notification"><X size={14}/></button></div>}
  </main>
}

function Overview({ role, setView, focus, setFocus }: { role: Role; setView: (v: View) => void; focus: string; setFocus: (s:string)=>void }) { return <div className="page overview"><section className="hero"><div className="hero-copy"><div className="eyebrow"><span></span>LIVE WATERSHED INTELLIGENCE</div><h1>See the story<br/>beneath the <i>surface.</i></h1><p>Transforming geo-coded field evidence into clear, timely action for India’s watersheds.</p><div className="hero-actions"><button className="primary" onClick={() => setView('gis')}>Explore live map <ArrowRight size={17}/></button><button className="ghost" onClick={() => setView('evidence')}><Camera size={17}/> View field evidence</button></div></div><div className="hero-orbit"><div className="orbit orbit-a"></div><div className="orbit orbit-b"></div><div className="water-globe"><span className="grid"></span><span className="land land-a"></span><span className="land land-b"></span><div className="pin pin-one"></div><div className="pin pin-two"></div></div><div className="live-tag"><span className="pulse"></span> 126 live observations</div></div></section>
    <section className="signal-bar"><div><Waves/><span><b>72%</b> Watershed health</span></div><div><CloudRain/><span><b>842 mm</b> Seasonal rainfall</span></div><div><Layers3/><span><b>34</b> Active interventions</span></div><div><Check/><span><b>91%</b> Field verified</span></div></section>
    <section className="section-heading"><div><span className="eyebrow">DECISION SIGNALS</span><h2>Where attention creates impact</h2></div><button className="text-btn" onClick={() => setView(role === 'public' ? 'indicator' : 'insights')}>Open spatial intelligence <ArrowRight size={16}/></button></section>
    <section className="signal-grid"><article className="priority-card"><div className="card-top"><span className="status amber">PRIORITY INTERVENTION</span><button><LocateFixed size={17}/></button></div><h3>Check dam performance needs field verification</h3><p>South-east drainage corridor shows a 14% decline in post-monsoon water retention.</p><div className="evidence-line"><div className="mini-photo"></div><span>Satellite change + 3 field images</span><ArrowRight size={16}/></div></article><article className="map-card"><div className="map-art"><div className="contours"></div><span className="map-label a">Ballyguda</span><span className="map-label b">Priority zone</span><span className="map-pin"></span><span className="river"></span></div><div className="map-caption"><div><small>FOCUS WATERSHED</small><b>{focus}</b></div><button onClick={() => setFocus(focus === 'Kandhamal Watershed' ? 'Tikabali Micro-watershed' : 'Kandhamal Watershed')}>Change <ChevronDown size={14}/></button></div></article><article className="impact-card"><span className="eyebrow">SEASONAL PROGRESS</span><div className="score"><span>68</span><small>/ 100</small></div><h3>Water resilience is improving</h3><div className="progress"><i></i></div><p>+8 points since 2025 baseline</p></article></section>
    <section className="story-strip"><div><span className="eyebrow">EVIDENCE TO ACTION</span><h2>From a field photo to a public good.</h2></div><div className="story-flow"><b><Camera/> Geo-image</b><i></i><b><Navigation/> Location context</b><i></i><b><Waves/> Watershed action</b></div></section>
    {role === 'government' && <section className="field-cta"><div><span className="eyebrow">FIELD OPERATIONS</span><h2>3 observations need your team’s attention.</h2><p>Coordinate verification, add evidence and close the loop.</p></div><button className="primary" onClick={() => setView('operations')}>Review operations <ArrowRight size={17}/></button></section>}
  </div> }

function GIS({ focus }: { focus: string }) { return <div className="page gis-page"><div className="gis-map"><div className="terrain"></div><div className="gis-grid"></div><div className="flow f1"></div><div className="flow f2"></div><div className="flow f3"></div><div className="boundary b1"></div><div className="boundary b2"></div><div className="map-marker m1"><i></i><span>Check dam</span></div><div className="map-marker m2"><i></i><span>Farm pond</span></div><div className="map-marker m3 alert"><i></i><span>Review needed</span></div><div className="gis-title"><span className="eyebrow">LIVE SPATIAL LAYER</span><h1>{focus}</h1><p>Terrain · hydrology · field evidence</p></div><div className="layer-panel"><div className="panel-head"><b>Map layers</b><Layers3 size={17}/></div><label><input type="checkbox" defaultChecked/> Watershed boundary</label><label><input type="checkbox" defaultChecked/> Drainage network</label><label><input type="checkbox" defaultChecked/> Field evidence</label><label><input type="checkbox"/> Rainfall intensity</label></div><div className="map-controls"><button>+</button><button>−</button><button><LocateFixed size={18}/></button></div><div className="map-legend"><span><i className="blue"></i> Drainage</span><span><i className="green"></i> Healthy cover</span><span><i className="amber-dot"></i> Attention</span></div></div></div> }
function Evidence({ navigate }: { navigate: (view: View) => void }) { const [selected, setSelected] = useState<string | null>(null); const [analysis, setAnalysis] = useState<string | null>(null); const cards = [['IMG-1024','Kovilur','WHS-021','11 Sep 2026 · 10:42'],['IMG-1025','Kovilur','WHS-028','10 Sep 2026 · 14:18'],['IMG-1028','Madurantakam','WHS-009','08 Sep 2026 · 09:05']]; return <div className="page content-page gov-evidence"><section className="content-hero"><span className="eyebrow">GEO-CODED FIELD EVIDENCE</span><h1>Evidence captured.<br/><i>Intelligence connected.</i></h1><p>GPS-linked images connect visual evidence to watershed assets, observations and field decisions.</p><button className="primary"><Upload size={17}/> Add field evidence</button></section><div className="evidence-journey"><Camera/> Image <i></i><LocateFixed/> GPS <i></i><Map/> GIS <i></i><Waves/> Watershed <i></i><Building2/> Asset <i></i><Activity/> Analysis</div><section className="gov-evidence-grid">{cards.map(([id,place,asset,date],i) => <article className="gov-evidence-card" key={id}><button className={'gov-image img-'+i} onClick={() => setSelected(id)}><span><Camera size={14}/> {id}</span><em><LocateFixed size={13}/> GPS verified</em><i><Search size={18}/></i></button><div className="gov-evidence-info"><div className="evidence-id"><span>{id}</span><small>FIELD EVIDENCE</small></div><h3>{place}</h3><p><LocateFixed size={14}/> 12.970000, 80.006000</p><p><Camera size={14}/> {date}</p><div className="evidence-meta"><span>Asset <b>{asset}</b></span><span>Water <b className="red-text">Poor</b></span><span>Condition <b className="amber-text">Moderate</b></span></div><footer><button onClick={() => setSelected(id)}>View</button><button onClick={() => setAnalysis(id)}>Analyze</button><button onClick={() => navigate('before-after')}>Compare</button><button onClick={() => navigate('gis')}>View on GIS</button></footer></div></article>)}</section>{selected && <GovernmentImageModal id={selected} close={() => setSelected(null)} analyze={() => setAnalysis(selected)} navigate={navigate}/>} {analysis && <AnalysisModal id={analysis} close={() => setAnalysis(null)}/>}</div> }
function GovernmentImageModal({ id, close, analyze, navigate }: { id: string; close: () => void; analyze: () => void; navigate: (view: View) => void }) { return <div className="image-modal gov-image-modal" onClick={close}><article onClick={e => e.stopPropagation()}><button className="modal-close" onClick={close}><X/></button><div className="modal-image img-0"></div><span className="eyebrow">GEO-CODED FIELD EVIDENCE</span><h2>{id} · Kovilur</h2><div className="modal-detail-grid"><span>GPS <b>12.970000, 80.006000</b></span><span>Captured <b>11 Sep 2026 · 10:42</b></span><span>Watershed <b>WS-001 · Kovilur</b></span><span>Village <b>Kovilur</b></span><span>Asset <b>WHS-021 · Check Dam</b></span><span>Officer <b>A. Suresh · Field Officer</b></span></div><section className="internal-observation"><b>Observation</b><p>Reduced water retention visible downstream of the check dam.</p><b>AI-assisted analysis</b><p>Possible degradation observed. Field verification recommended.</p><b>Internal notes</b><p>Schedule inspection with the Raikia field team after rainfall.</p></section><footer className="modal-actions"><button onClick={analyze}>Analyze Image</button><button onClick={() => navigate('before-after')}>Compare</button><button onClick={() => navigate('gis')}>View on GIS</button><button onClick={() => navigate('operations')}>Create Inspection</button><button onClick={() => navigate('observation')}>Create Observation</button></footer></article></div> }
function AnalysisModal({ id, close }: { id: string; close: () => void }) { const [step, setStep] = useState(0); useEffect(() => { if (step < 4) { const timer = window.setTimeout(() => setStep(step + 1), 750); return () => window.clearTimeout(timer) } }, [step]); const steps = ['Scanning visual evidence...', 'Reading geo-spatial context...', 'Comparing field indicators...', 'Generating observation...']; const results = [['Water Presence','82%'],['Vegetation','90%'],['Structure Damage','64%'],['Possible Erosion','51%']]; return <div className="image-modal analysis-modal"><article><button className="modal-close" onClick={close}><X/></button><span className="ripple-loader"><i></i><i></i><i></i></span><span className="eyebrow">AI-ASSISTED VISUAL OBSERVATION · {id}</span><h2>{step < 4 ? 'Analyzing visual evidence...' : 'Possible degradation observed.'}</h2>{step < 4 ? <div className="analysis-steps">{steps.map((text,i) => <p key={text} className={i <= step ? 'done' : ''}><span>{i < step ? <Check size={13}/> : i === step ? <i className="mini-ripple"></i> : i + 1}</span>{text}</p>)}</div> : <><div className="analysis-results">{results.map(([label,value],i) => <div key={label}><span>{label}<b>{value}</b></span><i><em style={{ width: value }}></em></i></div>)}</div><p className="analysis-note">AI-assisted visual observation. Field verification recommended.</p><p className="analysis-disclaimer">AI-assisted visual observation. Results require field verification and should not be treated as official ground truth.</p><button className="primary" onClick={close}>Close analysis</button></>}</article></div> }
function Insights() { return <div className="page content-page"><section className="content-hero"><span className="eyebrow">SPATIAL INTELLIGENCE</span><h1>Patterns that point<br/>to <i>better decisions.</i></h1></section><section className="insight-layout"><article className="heat-card"><div className="heatmap"><span className="hot h1"></span><span className="hot h2"></span><span className="hot h3"></span><div className="contours"></div></div><div><b>Intervention priority surface</b><p>Combines water stress, verified evidence and asset performance.</p></div></article><div className="insight-list"><article><AlertTriangle/><div><small>HIGH PRIORITY</small><h3>7 assets show declining retention</h3><p>Review field evidence before 30 Sep.</p></div><ArrowRight size={18}/></article><article><Leaf/><div><small>POSITIVE CHANGE</small><h3>Vegetation cover up 11.2%</h3><p>Compared with 2025 post-monsoon imagery.</p></div><ArrowRight size={18}/></article></div></section></div> }
function Operations({ navigate }: { navigate: (view: View) => void }) { const [detail, setDetail] = useState(false); const [notice, setNotice] = useState(''); const inspections = [['INS-2042','WHS-021','WS-001','Field Officer 07','11 Sep 2026','Moderate','High','Pending Verification'],['INS-2038','WHS-042','WS-001','Field Officer 03','09 Sep 2026','Good','Medium','Scheduled'],['INS-2016','WHS-087','WS-003','Field Officer 11','06 Sep 2026','Damaged','High','Pending Verification']]; return <div className="page content-page operations-page"><section className="operations-hero"><div><span className="eyebrow">FIELD OPERATIONS</span><h1>Verification,<br/><i>where it matters.</i></h1><p>Coordinate inspections, evidence and field observations across watershed assets.</p></div><button className="primary" onClick={() => navigate('observation')}><LocateFixed size={17}/> New field observation</button></section><section className="ops-kpis">{[['Pending Inspections','24','blue'],['Completed','182','green'],['Critical','8','red'],['Due This Week','14','amber']].map(([label,value,tone]) => <button key={label} className={tone} onClick={() => setNotice(`${label} filter applied.`)}><b>{value}</b><span>{label}</span><ArrowRight size={15}/></button>)}</section>{notice && <div className="toast"><Check size={15}/>{notice}</div>}<section className="inspection-table"><div className="inspection-heading"><div><span className="eyebrow">INSPECTION CENTER</span><h2>Active inspections</h2></div><button className="text-btn" onClick={() => setNotice('Showing this week’s inspection queue.')}>This week <ChevronDown size={15}/></button></div><div className="inspection-head"><span>Inspection ID</span><span>Asset / Watershed</span><span>Officer</span><span>Last inspection</span><span>Condition</span><span>Priority</span><span>Status</span><span></span></div>{inspections.map((row,i) => <article className="inspection-row" key={row[0]}><b>{row[0]}</b><span><b>{row[1]}</b><small>{row[2]}</small></span><span>{row[3]}</span><span>{row[4]}</span><span className={row[5] === 'Damaged' ? 'red-text' : 'amber-text'}>{row[5]}</span><span className={row[6] === 'High' ? 'priority-high' : 'priority-medium'}>{row[6]}</span><span className="inspection-status">{row[7]}</span><div className="inspection-actions"><button onClick={() => { setDetail(true); setNotice('Inspection detail opened.') }}>Start Inspection</button><button onClick={() => navigate('evidence')}>View Evidence</button></div></article>)}</section>{detail && <InspectionDrawer close={() => setDetail(false)} navigate={navigate}/>}</div> }
function InspectionDrawer({ close, navigate }: { close: () => void; navigate: (view: View) => void }) { const [message, setMessage] = useState(''); return <aside className="inspection-drawer"><button className="drawer-close" onClick={close}><X/></button><span className="eyebrow">INSPECTION DETAIL · INS-2042</span><h2>WHS-021<br/><i>Check Dam</i></h2><div className="inspection-location"><LocateFixed size={17}/><span>GPS location<br/><b>12.970000, 80.006000</b></span><button onClick={() => navigate('gis')}>Open GIS <ArrowRight size={14}/></button></div><div className="inspection-images"><div className="img-0"><small>Latest image · 11 Sep</small></div><div className="img-2"><small>Previous image · 12 Aug</small></div></div><div className="inspection-signals">{[['Water condition','Poor','red-text'],['Structure condition','Moderate','amber-text'],['Vegetation','Good','green-text'],['Erosion','Possible','amber-text'],['Silt / debris','Observed','amber-text']].map(([name,value,tone]) => <div key={name}><span>{name}</span><b className={tone}>{value}</b></div>)}</div><section className="remarks"><b>Previous inspection</b><p>Outlet flow was stable; light debris noted near spillway.</p><b>Current observation</b><p>Reduced water retention visible in current geo-coded evidence.</p><b>Officer remarks</b><p>Verify after next rainfall event and assess silt removal requirement.</p></section><footer className="drawer-actions"><button onClick={() => navigate('observation')}>Start Inspection</button><button onClick={() => setMessage('Inspection submitted for district review.')}>Submit Inspection</button><button onClick={() => setMessage('Asset marked for verification.')}>Mark for Verification</button></footer>{message && <div className="drawer-toast"><Check size={14}/>{message}</div>}</aside> }
function FieldObservation({ navigate }: { navigate: (view: View) => void }) { const [submitted, setSubmitted] = useState(false); const [water, setWater] = useState('Moderate'); const [condition, setCondition] = useState('Moderate'); const [vegetation, setVegetation] = useState('Good'); const [erosion, setErosion] = useState('No'); const [debris, setDebris] = useState('No'); const Select = ({ title, value, values, onChange }: { title: string; value: string; values: string[]; onChange: (v:string)=>void }) => <div className="field-select"><b>{title}</b><div>{values.map(item => <button key={item} className={value === item ? 'selected' : ''} onClick={() => onChange(item)}>{item}</button>)}</div></div>; return <div className="field-observation"><header className="field-header"><button onClick={() => navigate('operations')}><ArrowRight size={18}/></button><div><span className="eyebrow">FIELD OPERATIONS</span><h1>FIELD OBSERVATION</h1></div><span className="gps-live"><i></i> Location captured</span></header><main><section className="field-asset"><span>Asset</span><b>WHS-021 · Check Dam</b><small><LocateFixed size={14}/> 12.970000, 80.006000</small></section><button className="capture-image"><Camera size={26}/><span>Capture / Upload Geo-Coded Image</span><small>Camera and GPS metadata ready</small></button><section className="field-form"><Select title="Water" value={water} values={['Good','Moderate','Poor','None']} onChange={setWater}/><Select title="Condition" value={condition} values={['Good','Moderate','Damaged','Critical']} onChange={setCondition}/><Select title="Vegetation" value={vegetation} values={['Good','Moderate','Poor']} onChange={setVegetation}/><div className="field-duo"><Select title="Erosion" value={erosion} values={['Yes','No']} onChange={setErosion}/><Select title="Silt / Debris" value={debris} values={['Yes','No']} onChange={setDebris}/></div><label className="remarks-input">Remarks<textarea placeholder="Add field observation notes for verification..."></textarea></label></section><button className="submit-observation" onClick={() => setSubmitted(true)}><Check size={18}/> SUBMIT FIELD OBSERVATION</button></main>{submitted && <SuccessModal close={() => setSubmitted(false)} navigate={navigate}/>}</div> }
function SuccessModal({ close, navigate }: { close: () => void; navigate: (view: View) => void }) { return <div className="image-modal success-modal"><article><span className="success-check"><Check size={34}/></span><span className="eyebrow">OBSERVATION SUBMITTED</span><h2>WHS-021</h2><p>Geo-coded evidence successfully recorded.</p><div className="success-meta"><span>GPS <b>12.970000, 80.006000</b></span><span>Time <b>11 Sep 2026, 10:42 AM</b></span><span>Status <b>Pending Verification</b></span></div><footer><button onClick={() => { close(); navigate('operations') }}>View Observation</button><button onClick={() => { close(); navigate('gis') }}>View on Map</button></footer></article></div> }
function BeforeAfter() { const [position, setPosition] = useState(55); const [watershed, setWatershed] = useState('WS-001 · Kovilur'); const score = Math.round(position); const water = score > 64 ? 'Poor' : score > 38 ? 'Moderate' : 'Good'; const vegetation = score > 64 ? 'Sparse' : score > 38 ? 'Moderate' : 'Good'; const structure = score > 64 ? 'Damaged' : score > 38 ? 'Moderate' : 'Good'; return <div className="page content-page temporal-page"><section className="temporal-hero"><div><span className="eyebrow">TEMPORAL WATERSHED ANALYSIS</span><h1>See change.<br/><i>Understand impact.</i></h1><p>Compare dated geo-coded evidence to identify possible change requiring field verification.</p></div><div className="temporal-selects"><label>Watershed<select value={watershed} onChange={e => setWatershed(e.target.value)}><option>WS-001 · Kovilur</option><option>WS-003 · Madurantakam</option></select></label><label>Asset<select><option>WHS-021 · Check Dam</option><option>WHS-042 · Farm Pond</option></select></label><label>Date<select><option>Jun 2026 → Sep 2026</option></select></label></div></section><section className="comparison-stage"><div className="compare-label before">BEFORE <b>June 2026</b></div><div className="compare-label after">AFTER <b>September 2026</b></div><div className="compare-before"></div><div className="compare-after" style={{ clipPath: `inset(0 0 0 ${position}%)` }}></div><input aria-label="Comparison slider" type="range" min="0" max="100" value={position} onChange={e => setPosition(Number(e.target.value))}/><span className="comparison-handle" style={{ left: `${position}%` }}><i>↔</i></span></section><section className="comparison-results"><div><span className="eyebrow">COMPARISON RESULT</span><h2>POSSIBLE DEVELOPMENT DECLINE</h2><p>Requires field verification.</p></div><div className="temporal-indicators"><span>Water Presence <b>Good → <i className={water === 'Poor' ? 'red-text' : 'amber-text'}>{water}</i></b></span><span>Vegetation <b>Moderate → <i className={vegetation === 'Sparse' ? 'red-text' : 'amber-text'}>{vegetation}</i></b></span><span>Structure <b>Good → <i className={structure === 'Damaged' ? 'red-text' : 'amber-text'}>{structure}</i></b></span></div><div className="decline-signals"><span>↓ Water availability</span><span>↓ Vegetation</span><span>↓ Asset condition</span></div></section></div> }
function SpatialAnalytics() { const [loading, setLoading] = useState(true); const [active, setActive] = useState('Possible erosion'); const clusters: Record<string, [number, number][]> = { 'Possible erosion': [[12.955,79.977],[12.968,79.995],[12.987,79.982]], 'Visible deterioration': [[12.998,79.985],[12.968,80.003]], 'Declining water': [[12.981,79.959],[12.949,79.973]], 'Reduced vegetation': [[12.960,79.945],[12.976,79.999]] }; useEffect(() => { const timer = window.setTimeout(() => setLoading(false), 1200); return () => window.clearTimeout(timer) }, []); const insights = [['Possible erosion','18 locations','red'],['Visible deterioration','12 assets','amber'],['Declining water','9 locations','blue'],['Reduced vegetation','7 areas','purple']]; return <div className="analytics-page">{loading ? <div className="analytics-loading"><span className="ripple-loader"><i></i><i></i><i></i></span><p>Processing spatial indicators...</p></div> : <><div className="analytics-map-head"><span className="eyebrow">SPATIAL INTELLIGENCE</span><h1>Watershed Intelligence</h1><p>Spatial indicators and temporal patterns for focused field attention.</p></div><MapContainer center={[12.975,79.975]} zoom={12} scrollWheelZoom className="analytics-map"><TileLayer attribution="&copy; OpenStreetMap contributors" url="https://{s}.tile.openstreetmap.org/{z}/{x}/{y}.png"/>{Object.entries(clusters).flatMap(([name, points]) => points.map((point,i) => <CircleMarker key={`${name}-${i}`} center={point} radius={active === name ? 19 : 12} className={active === name ? 'analytics-active' : ''} pathOptions={{ color: name === 'Possible erosion' ? '#d9534f' : name === 'Visible deterioration' ? '#f4b942' : name === 'Declining water' ? '#168aad' : '#7667bf', fillColor: name === 'Possible erosion' ? '#d9534f' : name === 'Visible deterioration' ? '#f4b942' : name === 'Declining water' ? '#168aad' : '#7667bf', fillOpacity: active === name ? .55 : .28, weight: 2 }} eventHandlers={{ click: () => setActive(name) }}><Tooltip>{name} · priority cluster</Tooltip><Popup><div className="gov-popup"><b>{name}</b><small>Spatial indicator cluster</small><p>Prototype prioritization based on geo-coded images and spatial context.</p><footer><button>View evidence</button></footer></div></Popup></CircleMarker>))}</MapContainer><aside className="spatial-panel"><span className="eyebrow">SPATIAL INSIGHTS</span><h2>Priority patterns</h2>{insights.map(([name,count,tone]) => <button key={name} className={active === name ? 'active' : ''} onClick={() => setActive(name)}><span className={`spatial-dot ${tone}`}></span><div><b>{name}</b><small>{count}</small></div><ArrowRight size={15}/></button>)}<div className="analytics-layers"><b>Indicator layers</b>{['Problem Clusters','Low Water Zones','Vegetation Stress','Damaged Assets','Possible Erosion','Missing Observations'].map((layer,i) => <label key={layer}><input type="checkbox" defaultChecked={i < 4}/>{layer}</label>)}</div></aside><div className="analytics-story"><b>Geo-Coded Images</b><i></i><b>Spatial Indicators</b><i></i><b>Temporal Change</b><i></i><b>Problem Clusters</b><i></i><b>Priority Areas</b><small>Prototype analytical prioritization. Requires official verification.</small></div></>}</div> }
function GovernmentIndicator({ navigate }: { navigate: (view: View) => void }) { const parts = [['Water Status','25%'],['Vegetation','20%'],['Asset Condition','20%'],['Land Condition','20%'],['Field Evidence','15%']]; return <section className="government-indicator"><div className="indicator-ring"><b>82</b><small>/ 100</small><span>HEALTHY</span></div><div><span className="eyebrow">WS-001 · DEVELOPMENT INDICATOR</span><h2>Watershed health, made explainable.</h2><p>Supporting evidence and spatial context combine to guide focused attention.</p><div className="indicator-breakdown">{parts.map(([label,value]) => <span key={label}>{label}<b>{value}</b></span>)}</div><small className="indicator-disclaimer">Prototype analytical indicator — not an official government metric.</small></div><button className="text-btn" onClick={() => navigate('indicator')}>View full indicator breakdown <ArrowRight size={15}/></button></section> }
function PriorityIntervention({ navigate }: { navigate: (view: View) => void }) { const [selected, setSelected] = useState('WHS-021'); const priorities: Record<string, { level:string; position:[number,number]; reasons:string[] }> = { 'WHS-021': { level:'HIGH',position:[12.997,79.985],reasons:['Low water presence','Visible deterioration','Recent negative change','Spatial problem concentration'] }, 'WHS-042': { level:'MEDIUM',position:[12.968,79.955],reasons:['Moderate water stress','Evidence older than 30 days'] }, 'WHS-087': { level:'LOW',position:[12.953,80.000],reasons:['Stable condition','Routine review suggested'] } }; const current = priorities[selected]; return <div className="priority-page"><div className="priority-map-head"><span className="eyebrow">PRIORITY INTERVENTION MAP</span><h1>Where attention<br/><i>can create impact.</i></h1><p>Evidence-led prototype prioritization for watershed action.</p></div><MapContainer center={[12.975,79.975]} zoom={12} scrollWheelZoom className="priority-map"><TileLayer attribution="&copy; OpenStreetMap contributors" url="https://{s}.tile.openstreetmap.org/{z}/{x}/{y}.png"/>{Object.entries(priorities).map(([id,item]) => <CircleMarker key={id} center={item.position} radius={selected === id ? 19 : 13} className={item.level === 'HIGH' ? 'priority-pulse' : ''} pathOptions={{ color:item.level === 'HIGH' ? '#d9534f' : item.level === 'MEDIUM' ? '#f4b942' : '#2e8b57',fillColor:item.level === 'HIGH' ? '#d9534f' : item.level === 'MEDIUM' ? '#f4b942' : '#2e8b57',fillOpacity:.52,weight:2 }} eventHandlers={{ click:() => setSelected(id) }}><Tooltip>{id} · {item.level} priority</Tooltip></CircleMarker>)}</MapContainer><aside className="priority-detail"><span className={`priority-level ${current.level.toLowerCase()}`}>{current.level} PRIORITY</span><h2>{selected}</h2><small>WS-001 · Kovilur Watershed</small><div className="priority-reasons"><b>Reasons</b>{current.reasons.map(reason => <span key={reason}><AlertTriangle size={13}/>{reason}</span>)}</div><div className="priority-evidence"><b>Evidence</b><p>IMG-1024 · 11 Sep 2026<br/>Temporal change signal · Spatial cluster match</p></div><div className="recommended"><b>Recommended Action</b><span>Field verification</span></div><footer><button onClick={() => navigate('gis')}>View on Map</button><button onClick={() => navigate('evidence')}>View Evidence</button><button onClick={() => navigate('operations')}>Inspect</button></footer><p className="priority-disclaimer">Prototype analytical prioritization. Requires official verification.</p></aside><div className="priority-legend"><span><i className="high"></i>HIGH</span><span><i className="medium"></i>MEDIUM</span><span><i className="low"></i>LOW</span></div><div className="priority-logic">Image Observations <i>−</i> Asset Condition <i>−</i> Water Status <i>−</i> Vegetation <i>−</i> Historical Change <i>−</i> Spatial Concentration</div></div> }
function Reports({ navigate }: { navigate: (view: View) => void }) { const [generating, setGenerating] = useState<string | null>(null); const [preview, setPreview] = useState<string | null>(null); const [notice, setNotice] = useState(''); const reportIcons: typeof Waves[] = [Waves,Map,Building2,LocateFixed,Activity,AlertTriangle]; const reports: [string,string,typeof Waves][] = mockGovernmentReports.map((report,index) => [report.title, report.description, reportIcons[index] || FileText]); const generate = (name: string) => { setGenerating(name); window.setTimeout(() => { setGenerating(null); setPreview(name); setNotice('Report generated') }, 1050) }; return <div className="page content-page reports government-reports"><section className="content-hero"><span className="eyebrow">DECISION SUPPORT</span><h1>Government reporting,<br/><i>made actionable.</i></h1><p>Generate evidence-led prototype reports for monitoring and field coordination.</p></section><section className="report-grid">{reports.map(([title,text,Icon]) => <article key={title}><span className="report-icon"><Icon/></span><small>GOVERNMENT REPORT</small><h3>{title}</h3><p>{text}</p><button className="text-btn" onClick={() => generate(title)}>{generating === title ? 'Generating…' : 'Generate'} <ArrowRight size={16}/></button></article>)}</section>{generating && <div className="report-loading"><span className="ripple-loader"><i></i><i></i><i></i></span><p>Generating watershed report...</p></div>}{preview && <ReportPreview title={preview} close={() => setPreview(null)} navigate={navigate}/>} {notice && <div className="toast"><Check size={15}/>{notice}</div>}</div> }
function ReportPreview({ title, close, navigate }: { title: string; close: () => void; navigate: (view: View) => void }) { return <div className="image-modal report-preview" onClick={close}><article onClick={e => e.stopPropagation()}><button className="modal-close" onClick={close}><X/></button><span className="eyebrow">{title.toUpperCase()}</span><h2>WATERSHED DEVELOPMENT<br/>SUMMARY</h2><h3>WS-001 · Kovilur</h3><div className="report-summary"><span>Watersheds monitored <b>{watersheds.length}</b></span><span>Geo-coded images <b>{geoImages.length}</b></span><span>Spatial indicators <b>{spatialInsights.length}</b></span><span>Assets requiring review <b>{assets.filter(asset => asset.risk === 'high').length}</b></span><span>Field observations <b>{fieldObservations.length}</b></span></div><div className="report-priority"><b>Priority assets</b>{priorityZones.slice(0,3).map(zone => <span key={zone.id}>{zone.assetId}</span>)}</div>{title === 'AI Watershed Summary' && <p className="ai-report-note">AI-generated summary based on available prototype data. Officials should verify findings before taking administrative action.</p>}<footer><button onClick={() => navigate('gis')}>View on Map</button><button onClick={close}>Close Preview</button></footer></article></div> }
function Alerts({ navigate, openTarget }: { navigate: (view: View) => void; openTarget: (target:string)=>void }) { const [tab, setTab] = useState('All'); const [selected, setSelected] = useState<string | null>(null); const [reviewed, setReviewed] = useState<string[]>([]); const [notice, setNotice] = useState(''); const alerts = [{id:'ALT-042',level:'Critical',asset:'WHS-042',text:'WHS-042 shows visible structural deterioration.',target:'WHS-042',color:'critical'}, {id:'ALT-018',level:'High',asset:'WS-003',text:'Possible erosion detected across multiple geo-coded observations.',target:'WS-003',color:'high'}, {id:'ALT-031',level:'Medium',asset:'WHS-021',text:'Water presence declined across recent observations.',target:'WHS-021',color:'medium'}, {id:'ALT-067',level:'Information',asset:'WS-001',text:'No recent geo-coded observation available.',target:'WS-001',color:'information'}]; const visible = tab === 'All' ? alerts : alerts.filter(alert => alert.level === tab); const current = alerts.find(alert => alert.id === selected); const map = () => { if (!current) return; setSelected(null); openTarget(current.target); navigate('gis') }; const review = () => { if (!current) return; setReviewed(items => [...items, current.id]); setNotice(`${current.id} marked reviewed.`); setSelected(null) }; return <div className="page content-page alerts-page"><section className="alerts-hero"><span className="eyebrow">RISK MONITORING</span><h1>Signals that need<br/><i>attention.</i></h1><p>Prioritized monitoring signals from field evidence, spatial context and temporal change.</p></section><div className="alert-tabs">{['All','Critical','High','Medium','Information'].map(name => <button key={name} className={tab === name ? 'active' : ''} onClick={() => setTab(name)}>{name}</button>)}</div><section className="alert-list">{visible.map(alert => <article className={`alert-card ${alert.color}`} key={alert.id} onClick={() => setSelected(alert.id)}><span className="alert-level">{alert.level.toUpperCase()}</span><div><small>{alert.id} · {alert.asset}</small><h3>{alert.text}</h3><p>{reviewed.includes(alert.id) ? 'Reviewed' : 'Latest spatial signal · 11 Sep 2026'}</p></div><ArrowRight size={18}/></article>)}</section>{selected && current && <aside className="alert-drawer"><button className="drawer-close" onClick={() => setSelected(null)}><X/></button><span className={`alert-level ${current.color}`}>{current.level.toUpperCase()}</span><h2>{current.asset}</h2><p>{current.text}</p><div className="alert-detail"><span>Location <b>WS-003</b></span><span>Latest observation <b>11 Sep 2026</b></span><span>Evidence <b>3 geo-coded images</b></span></div><footer><button onClick={() => navigate('evidence')}>View Evidence</button><button onClick={map}>View on Map</button><button onClick={review}>Mark Reviewed</button></footer></aside>}{notice && <div className="toast"><Check size={15}/>{notice}</div>}</div> }

function GovernmentDashboard({ navigate, openTarget, onOpenKpi }: { navigate: (view: View) => void; openTarget: (target: string) => void; onOpenKpi: (metric: KpiMetric) => void }) {
  const { observations } = useWorkflow()
  const stats: [string, string, KpiMetric, typeof Waves][] = [['Total Watersheds',String(watersheds.length),'watersheds',Waves],['Geo-Coded Images',String(geoImages.length),'images',Camera],['Watershed Assets',String(assets.length),'assets',Building2],['Field Observations',String(observations.length),'observations',LocateFixed],['Priority Zones',String(priorityZones.length),'critical',AlertTriangle]]
  return <div className="page government-page"><section className="gov-welcome"><div><span className="eyebrow">WATER INTELLIGENCE</span><h1>Good morning, <i>District Officer.</i></h1><p>Monitor watershed development through geo-coded evidence and spatial intelligence.</p><button className="primary" onClick={() => navigate('gis')}>Open GIS Command Map <ArrowRight size={17}/></button></div><div className="gov-radar"><i></i><i></i><i></i><span className="radar-sweep"></span><b>{watersheds.length}</b><small>Active watersheds</small></div></section><section className="gov-kpis">{stats.map(([label,value,metric,Icon]) => <button key={label} className={metric === 'critical' ? 'critical-kpi' : ''} onClick={() => onOpenKpi(metric)} aria-label={`Open details for ${label}, ${value}`}><span><Icon size={18}/></span><b>{value}</b><small>{label}</small><ArrowRight size={15}/></button>)}</section><section className="gov-command-grid"><article className="command-map" role="button" tabIndex={0} onClick={() => navigate('gis')} onKeyDown={event => event.key === 'Enter' && navigate('gis')}><div className="contours"></div><span className="asset-dot a"></span><span className="asset-dot b"></span><span className="asset-dot c"></span><div><small>LIVE COMMAND VIEW</small><h3>{priorityZones.length} priority zones<br/>across the demo region</h3><button className="text-btn" onClick={event => { event.stopPropagation(); navigate('gis') }}>Open geospatial intelligence <ArrowRight size={15}/></button></div></article><article className="gov-feed"><span className="eyebrow">EVIDENCE SIGNALS</span><h3>Geo-coded intelligence, where it matters</h3>{mockAlerts.slice(0,3).map(alert => <button key={alert.id} onClick={() => { openTarget(alert.assetId); navigate('gis') }}><span className={`feed-dot f${alert.level === 'critical' ? 0 : alert.level === 'high' ? 1 : 2}`}></span>{alert.title} · {alert.location}<ArrowRight size={14}/></button>)}</article></section><GovernmentIndicator navigate={navigate}/></div>
}
const coords: Record<string, [number, number]> = { 'WS-001': [12.979, 79.970], 'WHS-021': [12.997, 79.985], 'WHS-042': [12.961, 79.952], 'WHS-087': [12.978, 80.005], 'WS-003': [12.945, 79.994], 'IMG-1024': [12.970, 80.006], 'IMG-1025': [12.976, 79.990], 'IMG-1028': [12.511, 79.884], 'WB-014': [12.982, 79.958], 'Kovilur': [12.962, 79.940] }
function FlyToTarget({ target, clear }: { target: string | null; clear: () => void }) { const map = useMap(); useEffect(() => { if (target && coords[target]) { map.flyTo(coords[target], 15, { duration: 1.1 }); const timer = window.setTimeout(clear, 1400); return () => window.clearTimeout(timer) } }, [target, map, clear]); return null }
function ObservationFocus({ coordinates }: { coordinates: [number, number] | null }) { const map = useMap(); useEffect(() => { if (coordinates) map.flyTo(coordinates, 16, { duration: 1.1 }) }, [coordinates, map]); return null }
function GovMarker({ id, color, children, target, onClick, tooltip }: { id: string; color: string; children: React.ReactNode; target: string | null; onClick: () => void; tooltip: string }) { const marker = useRef<any>(null); useEffect(() => { if (target === id) window.setTimeout(() => marker.current?.openPopup(), 800) }, [target, id]); return <CircleMarker ref={marker} center={coords[id]} radius={target === id ? 14 : 10} pathOptions={{ color, fillColor: color, fillOpacity: .86, weight: target === id ? 5 : 2 }} eventHandlers={{ click: onClick }}><Tooltip direction="top" offset={[0, -9]}>{tooltip}</Tooltip><Popup>{children}</Popup></CircleMarker> }
function GovernmentGIS({ target, observationPoint, clearTarget, navigate, onSelectWatershed, onSelectAsset, onOpenEvidence, onAnalyzeEvidence, onCompareEvidence }: { target: string | null; observationPoint: [number, number] | null; clearTarget: () => void; navigate: (view: View) => void; onSelectWatershed: (id: string) => void; onSelectAsset: (id: string) => void; onOpenEvidence: (id: string) => void; onAnalyzeEvidence: (id: string) => void; onCompareEvidence: (id: string) => void }) {
  const [layers, setLayers] = useState({ watersheds: true, sub: true, water: true, assets: true, images: true, agriculture: true, villages: true, priority: true, risk: true })
  const [selected, setSelected] = useState<string | null>(target); const [search, setSearch] = useState('')
  const toggle = (key: keyof typeof layers) => setLayers(x => ({ ...x, [key]: !x[key] }))
  useEffect(() => setSelected(target), [target])
  const watershed = { type: 'Feature' as const, properties: {}, geometry: { type: 'Polygon' as const, coordinates: [[[79.919,12.946],[80.001,12.946],[80.024,12.990],[79.965,13.016],[79.913,12.982],[79.919,12.946]]] } }
  const agriculture = { type: 'Feature' as const, properties: { label: 'Agriculture area' }, geometry: { type: 'Polygon' as const, coordinates: [[[79.925,12.949],[79.951,12.947],[79.966,12.963],[79.950,12.979],[79.929,12.972],[79.925,12.949]]] } }
  const priorityZones = [{ id: 'PZ-01', center: [12.945,79.994] as [number,number], level: 'High', color: '#ed9d2b' }, { id: 'PZ-02', center: [12.988,79.958] as [number,number], level: 'Medium', color: '#f4b942' }, { id: 'PZ-03', center: [12.968,80.013] as [number,number], level: 'Low', color: '#dcc252' }]
  const riskZones = [{ id: 'RZ-01', center: [12.954,79.977] as [number,number], level: 'High', color: '#d9534f' }, { id: 'RZ-02', center: [12.987,79.994] as [number,number], level: 'Moderate', color: '#e77c59' }, { id: 'RZ-03', center: [12.949,79.953] as [number,number], level: 'Low', color: '#e7a94a' }]
  const find = () => { const input = search.trim().toLowerCase(); const id = Object.keys(coords).find(key => key.toLowerCase() === input); if (id) setSelected(id); else setSearch('No matching ID') }
  const marker = (id: string, color: string, tooltip: string, content: React.ReactNode) => <GovMarker id={id} color={color} target={selected} onClick={() => { setSelected(id); if (id.startsWith('WS-')) onSelectWatershed(id); if (id.startsWith('WHS-')) onSelectAsset(id) }} tooltip={tooltip}>{content}</GovMarker>
  return <div className="gov-gis">
    <div className="gov-gis-head"><span className="eyebrow">GEOSPATIAL INTELLIGENCE</span><h1>Government GIS Command Map</h1><p>Evidence, assets, risk and watershed context in one operational view.</p></div>
    <div className="gov-search"><Search size={16}/><input value={search} onChange={e => setSearch(e.target.value)} placeholder="Search ID or location" onKeyDown={e => e.key === 'Enter' && find()}/><button onClick={find}>Find</button></div>
    <MapContainer center={coords['WS-001']} zoom={12} scrollWheelZoom className="gov-leaflet"><TileLayer attribution="&copy; OpenStreetMap contributors" url="https://{s}.tile.openstreetmap.org/{z}/{x}/{y}.png"/><FlyToTarget target={selected} clear={clearTarget}/><ObservationFocus coordinates={observationPoint}/>
      {layers.watersheds && <><GeoJSON data={watershed} style={{ color: '#0b5fa5', weight: 2, fillColor: '#2ec4c7', fillOpacity: .12 }}/>{marker('WS-001','#0b5fa5','WS-001 · Kovilur Watershed',<WatershedPopup navigate={navigate} onSelect={() => onSelectWatershed('WS-001')}/>)}{marker('WS-003','#0b5fa5','WS-003 · Madurantakam Watershed',<div className="gov-popup"><b>WS-003 · Madurantakam</b><small>Government watershed risk context</small><p>Review spatial risk and field observations for this watershed.</p><button type="button" onClick={() => onSelectWatershed('WS-003')}>View watershed details</button><button type="button" onClick={() => navigate('insights')}>View Spatial Analytics</button></div>)}</>}
      {layers.sub && <GeoJSON data={{ ...watershed, geometry: { ...watershed.geometry, coordinates: [[[79.945,12.96],[79.985,12.96],[79.997,12.982],[79.958,12.995],[79.945,12.96]]] } } as any} style={{ color: '#2e8b57', weight: 1, dashArray: '5 5', fillOpacity: 0 }}/>} 
      {layers.water && marker('WB-014','#168aad','WB-014 · Water Body',<WaterPopup navigate={navigate}/>)}
      {layers.assets && <>{marker('WHS-021','#d9534f','WHS-021 · Check Dam · High Priority',<AssetPopup navigate={navigate} onSelect={() => onSelectAsset('WHS-021')}/>)}{marker('WHS-042','#f4b942','WHS-042 · Farm Pond',<AssetPopup navigate={navigate} onSelect={() => onSelectAsset('WHS-042')}/>)}{marker('WHS-087','#f4b942','WHS-087 · Recharge Structure',<AssetPopup navigate={navigate} onSelect={() => onSelectAsset('WHS-087')}/>)}</>}
      {layers.images && <>{marker('IMG-1024','#0b5fa5','IMG-1024 · Kovilur',<ImagePopup id="IMG-1024" onOpenEvidence={onOpenEvidence} onAnalyzeEvidence={onAnalyzeEvidence} onCompare={() => onCompareEvidence('IMG-1024')}/>)}{marker('IMG-1025','#0b5fa5','IMG-1025 · Kovilur',<ImagePopup id="IMG-1025" onOpenEvidence={onOpenEvidence} onAnalyzeEvidence={onAnalyzeEvidence} onCompare={() => onCompareEvidence('IMG-1025')}/>)}{marker('IMG-1028','#0b5fa5','IMG-1028 · Madurantakam',<ImagePopup id="IMG-1028" onOpenEvidence={onOpenEvidence} onAnalyzeEvidence={onAnalyzeEvidence} onCompare={() => onCompareEvidence('IMG-1028')}/>)}</>}
      {layers.villages && marker('Kovilur','#2e8b57','Kovilur · Village',<VillagePopup navigate={navigate}/>)}
      {layers.agriculture && <GeoJSON data={agriculture} style={{ color: '#55986a', weight: 1, fillColor: '#72b77a', fillOpacity: .24 }}/>}
      {layers.priority && priorityZones.map(zone => <CircleMarker key={zone.id} center={zone.center} radius={zone.level === 'High' ? 21 : zone.level === 'Medium' ? 17 : 14} pathOptions={{ className: 'priority-glow', color: zone.color, fillColor: zone.color, fillOpacity: .2, weight: 2, dashArray: '4 5' }}><Tooltip>Priority · {zone.level}</Tooltip><Popup><div className="gov-popup"><b>PRIORITY ZONE · {zone.level.toUpperCase()}</b><small>{zone.id} · Updated 17/09/2026</small><p>Priority: <strong>{zone.level}</strong><br/>Review watershed evidence and confirm through field inspection.</p></div></Popup></CircleMarker>)}
      {layers.risk && riskZones.map(zone => <CircleMarker key={zone.id} center={zone.center} radius={zone.level === 'High' ? 23 : 18} pathOptions={{ className: 'risk-glow', color: zone.color, fillColor: zone.color, fillOpacity: .13, weight: 2 }}><Tooltip>Risk · {zone.level}</Tooltip><Popup><div className="gov-popup"><b>RISK ZONE · {zone.level.toUpperCase()}</b><small>{zone.id} · Updated 17/09/2026</small><p>Risk: <strong>{zone.level}</strong><br/>Spatial indicator for government review.</p></div></Popup></CircleMarker>)}
      {observationPoint && <CircleMarker center={observationPoint} radius={14} pathOptions={{ color: '#ecfbff', fillColor: '#1a9ba5', fillOpacity: .96, weight: 4 }}><Tooltip permanent direction="top">FIELD GPS</Tooltip><Popup><div className="gov-popup"><b>FIELD OBSERVATION LOCATION</b><small>Captured device GPS</small><p>Coordinates: <strong>{observationPoint[0].toFixed(6)}, {observationPoint[1].toFixed(6)}</strong><br/>Status: Pending Verification</p></div></Popup></CircleMarker>}
      <GovernmentMapControls/>
    </MapContainer>
    <div className="gov-layer-card"><b><Layers3 size={16}/> Operational layers</b>{([['watersheds','Watersheds'],['sub','Sub-Watersheds'],['water','Water Bodies'],['assets','Watershed Assets'],['images','Geo-Coded Images'],['agriculture','Agriculture'],['villages','Villages'],['priority','Priority Zones'],['risk','Risk Zones']] as const).map(([key,label]) => <label key={key}><input type="checkbox" checked={layers[key]} onChange={() => toggle(key)}/>{label}</label>)}</div><div className="gov-legend"><b>Legend</b><span><i className="legend-water"></i>Water body</span><span><i className="legend-asset"></i>Asset</span><span><i className="legend-priority"></i>Priority</span><span><i className="legend-risk"></i>Risk</span></div>
  </div>
}
