function PublicEvidence() { const [selected, setSelected] = useState<string | null>(null); const images = [['IMG-1024', 'Kovilur', '11 Sep 2026', 'WHS-021'], ['IMG-1025', 'Kovilur', '08 Sep 2026', 'WHS-028'], ['IMG-1028', 'Madurantakam', '02 Sep 2026', 'WHS-009']]; return <div className="page content-page public-evidence"><section className="content-hero"><span className="eyebrow">PUBLIC GEO-CODED IMAGES</span><h1>See development<br/><i>on the ground.</i></h1><p>Approved images are shared to make watershed development easy to understand.</p></section><div className="evidence-grid">{images.map(([id, place, date, asset], i) => <article className="evidence-card" key={id}><button className={'evidence-img img-'+i} onClick={() => setSelected(id)}><span><Camera size={16}/> Public image</span><i><Search size={17}/></i></button><div><small>{id}</small><h3>{place}</h3><p>{date} · {asset}</p><div className="public-image-stats"><span>Water <b>Poor</b></span><span>Condition <b>Moderate</b></span></div><footer><button onClick={() => setSelected(id)}>View</button><button onClick={() => setSelected(id)}>View Location</button><button onClick={() => setSelected(id)}>Compare</button></footer></div></article>)}</div>{selected && <ImageModal id={selected} close={() => setSelected(null)}/>}</div> }
